//! Per-site score terms must match PMDtools 0.60 on every row of
//! tests/data/pmdtools_site_terms.tsv (generated by tests/oracle/gen_site_terms.py).

use pmdshodh::model::{Params, site_term_ds, site_term_ss};

const TOLERANCE: f64 = 1e-12;

#[test]
fn site_terms_match_pmdtools_0_60() {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/data/pmdtools_site_terms.tsv"
    );
    let text = std::fs::read_to_string(path).expect("read reference table");

    let (mut ds_rows, mut ss_rows, mut worst) = (0usize, 0usize, 0f64);
    for line in text
        .lines()
        .filter(|l| !l.starts_with('#') && !l.starts_with("mode"))
    {
        let f: Vec<&str> = line.split('\t').collect();
        assert_eq!(f.len(), 10, "bad row: {line}");
        let z: u32 = f[1].parse().unwrap();
        let y: u32 = f[2].parse().unwrap();
        let q: u8 = f[3].parse().unwrap();
        let is_match = f[4] == "1";
        let params = Params {
            p: f[5].parse().unwrap(),
            c: f[6].parse().unwrap(),
            pi_ancient: f[7].parse().unwrap(),
            pi_contamination: f[8].parse().unwrap(),
        };
        let expected: f64 = f[9].parse().unwrap();
        let got = match f[0] {
            "ds" => {
                ds_rows += 1;
                site_term_ds(is_match, z, q, &params)
            }
            "ss" => {
                ss_rows += 1;
                site_term_ss(is_match, z, y, q, &params)
            }
            other => panic!("unknown mode {other}"),
        };
        let diff = (got - expected).abs();
        assert!(
            diff <= TOLERANCE,
            "{line}: got {got}, PMDtools {expected}, diff {diff}"
        );
        worst = worst.max(diff);
    }
    // Guard against a silently empty or truncated table.
    assert_eq!((ds_rows, ss_rows), (4320, 1092));
    println!("compared {ds_rows} ds + {ss_rows} ss rows; largest difference {worst:e}");
}
